/* compacto-ui — design tokens.
 *
 * Plain custom properties, no Tailwind at-rules, so this file is importable by
 * anything. These are PRE-THEME DEFAULTS: they keep the app-* utilities
 * meaningful during SSR and before hydration, and are overwritten wholesale at
 * runtime by appThemeCssVars() from "@/lib/color-themes".
 *
 * The .dark block exists for that same pre-hydration window and for
 * third-party CSS that keys off the class (Monaco, KaTeX, shiki). Component
 * classes in this library carry no dark: variants — see theme.css. */

:root {
  /* Rounded blocks — modern minimal corners. */
  --radius: 0.625rem;

  /* Motion tokens — every animation references these, no magic numbers.
     Enter = standard ease; exit = accelerate ease + ~30% shorter. */
  --motion-duration-instant: 80ms;
  --motion-duration-fast: 150ms;
  --motion-duration-base: 220ms;
  --motion-duration-slow: 320ms;
  --motion-ease-standard: cubic-bezier(0.2, 0, 0, 1);
  --motion-ease-accelerate: cubic-bezier(0.4, 0, 1, 1);
  --motion-ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);

  /* Strength of the decorative panel texture (texture.css) — 0 to 1. Set it
     on an ancestor to tune one panel, here to tune all of them. */
  --app-texture-alpha: 0.05;

  /* --- Surfaces --- */
  --app-bg: #f8fafc;
  --app-panel: #ffffff;
  --app-sidebar: #ffffff;
  --app-hover: rgba(15, 23, 42, 0.04);
  --app-selected: rgba(20, 20, 20, 0.07);

  /* --- Lines --- */
  --app-border: #e2e8f0;
  --app-border-mid: #cbd5e1;
  --app-border-accent: rgba(20, 20, 20, 0.25);

  /* --- Accent (single voice) --- */
  --app-accent: #141414;
  --app-accent-dim: rgba(20, 20, 20, 0.55);
  --app-accent-faint: rgba(20, 20, 20, 0.08);

  /* --- Type --- */
  --app-text: #334155;
  --app-bright: #0f172a;
  --app-dim: #64748b;

  /* --- Code surfaces --- */
  --app-editor: #ffffff;
  --app-gutter: #f8fafc;

  /* --- Status --- */
  --app-success: #10b981;
  --app-warn: #f59e0b;
  --app-error: #ef4444;

  /* Foreground for solid accent blocks. Stays legible on bright dark-theme
     accents and dark light-theme accents alike. */
  --app-on-solid: #ffffff;
}

.dark {
  --app-bg: #0b0d12;
  --app-panel: #14171f;
  --app-sidebar: #0b0d12;
  --app-hover: rgba(255, 255, 255, 0.04);
  --app-selected: rgba(244, 244, 245, 0.08);

  --app-border: #262b38;
  --app-border-mid: #333a4a;
  --app-border-accent: rgba(244, 244, 245, 0.25);

  --app-accent: #f4f4f5;
  --app-accent-dim: rgba(244, 244, 245, 0.55);
  --app-accent-faint: rgba(244, 244, 245, 0.08);

  --app-text: #9aa3b5;
  --app-bright: #e5e7eb;
  --app-dim: rgba(154, 163, 181, 0.8);

  --app-editor: #0b0d12;
  --app-gutter: #14171f;

  --app-success: #34d399;
  --app-warn: #fbbf24;
  --app-error: #f87171;

  --app-on-solid: #0b0d12;
}

/* Accessibility — honour reduced-motion: drop transforms/slides, keep only
   short opacity changes. Motion is feedback, never a gate. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: var(--motion-duration-fast) !important;
    transition-property: opacity !important;
    scroll-behavior: auto !important;
  }
}

/* compacto-ui — Tailwind v4 theme layer.
 *
 * `@theme inline` is mandatory here, not a style choice: the --color-app-*
 * entries must stay as var(--app-*) REFERENCES so the ten runtime palettes can
 * repaint them by writing --app-* onto documentElement. A plain `@theme` would
 * resolve and freeze today's hex values into the generated utilities, and every
 * palette but the default would silently stop working. */

@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  /* The app-* namespace -> Tailwind utilities (bg-app-panel, text-app-dim,
     border-app-border-accent, ...). This is the ONLY color vocabulary the
     library speaks. */
  --color-app-bg: var(--app-bg);
  --color-app-panel: var(--app-panel);
  --color-app-sidebar: var(--app-sidebar);
  --color-app-hover: var(--app-hover);
  --color-app-selected: var(--app-selected);
  --color-app-border: var(--app-border);
  --color-app-border-mid: var(--app-border-mid);
  --color-app-border-accent: var(--app-border-accent);
  --color-app-accent: var(--app-accent);
  --color-app-accent-dim: var(--app-accent-dim);
  --color-app-accent-faint: var(--app-accent-faint);
  --color-app-text: var(--app-text);
  --color-app-bright: var(--app-bright);
  --color-app-dim: var(--app-dim);
  --color-app-editor: var(--app-editor);
  --color-app-gutter: var(--app-gutter);
  --color-app-success: var(--app-success);
  --color-app-warn: var(--app-warn);
  --color-app-error: var(--app-error);
  --color-app-on-solid: var(--app-on-solid);

  /* Font namespaces the primitives use. The consumer supplies the actual faces
     by setting --app-font-* in its own :root (typically to a next/font CSS
     variable); unset, these fall back to system stacks so the package still
     looks deliberate standalone.

     The vocabulary is the type rule the design system is built on: aside from
     code, every string is either a TITLE or a DESCRIPTION. */
  --font-sans: var(--app-font-sans, ui-sans-serif, system-ui, sans-serif);
  --font-description: var(--app-font-description, var(--font-sans));
  --font-title: var(--app-font-title, var(--font-sans));
  --font-display: var(--app-font-display, var(--font-title));
  --font-mono: var(
    --app-font-mono,
    ui-monospace,
    SFMono-Regular,
    Menlo,
    monospace
  );
}

/* Flat "tag" fill: a tinted block derived from the element's own text color,
   so a tag needs one color decision instead of three. Tailwind's /opacity
   modifier is a no-op on currentColor, hence the explicit color-mix. */
@utility tint-current {
  background-color: color-mix(in srgb, currentColor 12%, transparent);
  border-color: color-mix(in srgb, currentColor 28%, transparent);
}

/* Overlay motion, owned here so the package has zero CSS peer dependencies.
   Every floating surface — tooltip, popover, menu, select, dialog — rises 6px
   into place rather than scaling. The consuming apps previously got this from
   tw-animate-css; the library deliberately does not depend on it. */
@keyframes compacto-fade-up {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes compacto-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes compacto-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

/* Alias kept so class strings ported from the apps stay byte-identical during
   migration. Scheduled for removal once both consumers are on the package. */
@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* compacto-ui — panel textures.
 *
 * A subtle decorative wash for a side panel, so its surface reads as a
 * distinct layer from the work area rather than flat filler. Sidebar and
 * SidebarRail apply one through their `texture` prop.
 *
 * Plain classes rather than Tailwind utilities, on purpose. The pattern lives
 * on a ::before pseudo-element — generated first, so real children paint over
 * it — and a pseudo-element needs a real selector to hang off. Each pattern is
 * also several offset gradient layers, more than an arbitrary-value string can
 * hold cleanly.
 *
 * Every color is color-mix()ed from --app-accent, never a literal hex, so the
 * wash follows whichever palette is active. Strength comes from
 * --app-texture-alpha (see tokens.css); set it on any ancestor to tune one
 * panel, or on :root to tune all of them. */

.compacto-texture--checker,
.compacto-texture--dots,
.compacto-texture--graph {
  position: relative;
}

.compacto-texture--checker::before,
.compacto-texture--dots::before,
.compacto-texture--graph::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: var(--app-texture-alpha, 0.05);
}

.compacto-texture--checker::before {
  background-image:
    linear-gradient(
      135deg,
      color-mix(in oklab, var(--app-accent) 45%, transparent) 25%,
      transparent 25%
    ),
    linear-gradient(225deg, var(--app-accent) 25%, transparent 25%),
    linear-gradient(
      315deg,
      color-mix(in oklab, var(--app-accent) 45%, transparent) 25%,
      transparent 25%
    ),
    linear-gradient(45deg, var(--app-accent) 25%, transparent 25%);
  background-position:
    -10px 0,
    -10px 0,
    0 0,
    0 0;
  background-size: 20px 20px;
}

.compacto-texture--dots::before {
  background-image:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 19px,
      var(--app-accent) 19px,
      var(--app-accent) 20px,
      transparent 20px,
      transparent 39px,
      var(--app-accent) 39px,
      var(--app-accent) 40px
    ),
    repeating-linear-gradient(
      90deg,
      transparent,
      transparent 19px,
      var(--app-accent) 19px,
      var(--app-accent) 20px,
      transparent 20px,
      transparent 39px,
      var(--app-accent) 39px,
      var(--app-accent) 40px
    ),
    radial-gradient(
      circle at 20px 20px,
      var(--app-accent) 1.6px,
      transparent 2.1px
    ),
    radial-gradient(
      circle at 0px 0px,
      var(--app-accent) 1.2px,
      transparent 1.7px
    ),
    radial-gradient(
      circle at 40px 0px,
      var(--app-accent) 1.2px,
      transparent 1.7px
    ),
    radial-gradient(
      circle at 0px 40px,
      var(--app-accent) 1.2px,
      transparent 1.7px
    ),
    radial-gradient(
      circle at 40px 40px,
      var(--app-accent) 1.2px,
      transparent 1.7px
    );
  background-size: 40px 40px;
}

.compacto-texture--graph::before {
  background-image:
    linear-gradient(var(--app-accent) 2px, transparent 2px),
    linear-gradient(90deg, var(--app-accent) 2px, transparent 2px),
    linear-gradient(
      color-mix(in oklab, var(--app-accent) 55%, transparent) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      color-mix(in oklab, var(--app-accent) 55%, transparent) 1px,
      transparent 1px
    );
  background-size:
    50px 50px,
    50px 50px,
    10px 10px,
    10px 10px;
  background-position:
    -2px -2px,
    -2px -2px,
    -1px -1px,
    -1px -1px;
}

/* compacto-ui — the one import this app's Tailwind entry needs.
 *
 *   @import "tailwindcss";
 *   @import "../styles/index.css";
 *
 * Order matters: tokens define the custom properties, theme maps them into
 * Tailwind's namespace, texture holds the plain classes Sidebar's `texture`
 * prop applies. */
@import "./tokens.css";
@import "./theme.css";
@import "./texture.css";
